import{_ as n,o as a,c as i,ag as l}from"./chunks/framework.PVHj0As1.js";const e="/pub-blog/assets/image-20240828222453973.CEZ8a0bs.png",p="/pub-blog/assets/image-20240828222047223.B6dXaIzy.png",t="/pub-blog/assets/image-20240828224125035.DRHlg2bw.png",r="/pub-blog/assets/image-20240828224918956.IDVfA43P.png",h="/pub-blog/assets/image-20240828225611828.BezozC9n.png",k="/pub-blog/assets/image-20240828225832286.Cz3e2-Zj.png",E="/pub-blog/assets/image-20240828230419298.DAEleZ73.png",c="/pub-blog/assets/PixPin_2024-08-28_23-19-49.E2-fQMyM.gif",o="/pub-blog/assets/image-20240828232352345.BORY_Z8D.png",A=JSON.parse('{"title":"三文带你轻松上手鸿蒙的AI语音01-实时语音识别","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/三文带你轻松上手鸿蒙的AI语音/三文带你轻松上手鸿蒙的AI语音01-实时语音识别/01-实时语音识别.md","filePath":"鸿蒙开发技巧/三文带你轻松上手鸿蒙的AI语音/三文带你轻松上手鸿蒙的AI语音01-实时语音识别/01-实时语音识别.md","lastUpdated":1730788610000,"__rawMarkdown":"# 三文带你轻松上手鸿蒙的AI语音01-实时语音识别\\n\\n## 前言\\n\\n**HarmonyOSNext**中集成了强大的AI功能。Core Speech Kit（基础语音服务）是它提供的众多AI功能中的一种。\\n\\nCore Speech Kit（基础语音服务）集成了语音类基础AI能力，包括文本转语音（TextToSpeech）及语音识别（SpeechRecognizer）能\\n\\n力，便于用户与设备进行互动，实现将实时输入的语音与文本之间相互转换。\\n\\n简单来讲Core Speech Kit主要提供了两大语音AI功能：\\n\\n1. **语音识别**\\n2. **文本转语音**\\n\\n## 语音识别介绍\\n\\n**语音识别功能**可以将一段音频信息（短语音模式不超过60s，长语音模式不超过8h）转换为文本。\\n\\n其中语音识别又可以实现：\\n\\n1. **实时语音转文本** \\n2. **声音文件转文本**\\n\\n## **实时语音转文本** \\n\\n### 实现流程\\n\\n先介绍语音识别的流程，后面的文字转语音大同小异\\n\\n1. 申请权限\\n2. 创建AI语音引擎\\n3. 设置监听回调\\n4. 开始监听\\n\\n\\n\\n\\n\\n>  tips: 完整代码在每一个功能的末尾，可以结合封装后的代码来阅读\\n\\n## 申请权限\\n\\n![image-20240828222453973](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828222453973.png)\\n\\n因为在开发功能过程中，需要调用手机的麦克风功能。所以需要主动申请权限。\\n\\n![image-20240828222047223](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828222047223.png)\\n\\n申请权限分成3个步骤\\n\\n1. 声明权限\\n2. 检查是否拥有权限\\n3. 申请权限\\n\\n### 声明权限\\n\\n1. 在`\\\\entry\\\\src\\\\main\\\\module.json5`中添加以下配置代码 *requestPermissions*\\n\\n   ```json\\n   {\\n     \\"module\\": {\\n       ...\\n       \\"requestPermissions\\": [\\n         {\\n           \\"name\\": \\"ohos.permission.MICROPHONE\\",\\n           \\"reason\\": \\"$string:voice_reason\\",\\n           \\"usedScene\\": {\\n             \\"abilities\\": [\\n               \\"FormAbility\\"\\n             ],\\n             \\"when\\": \\"always\\"\\n           }\\n         }\\n       ],\\n     }\\n   }\\n   ```\\n\\n   \\n\\n2. 在`\\\\entry\\\\src\\\\main\\\\resources\\\\base\\\\element\\\\string.json` 添加 申请原因 `voice_reason`\\n\\n   ```json\\n   {\\n     \\"string\\": [\\n       {\\n         \\"name\\": \\"module_desc\\",\\n         \\"value\\": \\"module description\\"\\n       },\\n       {\\n         \\"name\\": \\"EntryAbility_desc\\",\\n         \\"value\\": \\"description\\"\\n       },\\n       {\\n         \\"name\\": \\"EntryAbility_label\\",\\n         \\"value\\": \\"label\\"\\n       },\\n       {\\n         \\"name\\": \\"voice_reason\\",\\n         \\"value\\": \\"用于获取用户的录音\\"\\n       }\\n     ]\\n   }\\n   ```\\n\\n\\n\\n### 检查权限\\n\\n实际开发中，我们在申请权限之前可以先调用接口`checkAccessTokenSync`，检查下是否已经拥有权限。如果没有，则主动申请权限\\n\\n### 申请权限\\n\\n当我们需要申请某个功能的权限时，可以通过调用 `requestPermissionsFromUser` 来实现\\n\\n\\n\\n### 封装好的权限代码\\n\\n因为**HarmonyOSNext**中关于权限的代码，都是没有经过封装的，难以使用。所以这里提供了封装好的版本。\\n\\n没有封装过的示例代码：\\n\\n![image-20240828224125035](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828224125035.png)\\n\\n---\\n\\n封装好的代码\\n\\n`entry\\\\src\\\\main\\\\ets\\\\utils\\\\permissionMananger.ets`\\n\\n```\\n// 导入必要的模块，包括权限管理相关的功能\\nimport { abilityAccessCtrl, bundleManager, common, Permissions } from \'@kit.AbilityKit\';\\n\\nexport class PermissionManager {\\n  // 静态方法用于检查给定的权限是否已经被授予\\n  static checkPermission(permissions: Permissions[]): boolean {\\n    // 创建一个访问令牌管理器实例\\n    let atManager: abilityAccessCtrl.AtManager = abilityAccessCtrl.createAtManager();\\n    // 初始化tokenID为0，稍后将获取真实的tokenID\\n    let tokenID: number = 0;\\n\\n    // 获取本应用的包信息\\n    const bundleInfo =\\n      bundleManager.getBundleInfoForSelfSync(bundleManager.BundleFlag.GET_BUNDLE_INFO_WITH_APPLICATION);\\n\\n    // 设置tokenID为应用的访问令牌ID\\n    tokenID = bundleInfo.appInfo.accessTokenId;\\n\\n    // 如果没有传入任何权限，则返回false表示没有权限\\n    if (permissions.length === 0) {\\n      return false;\\n    } else {\\n      // 检查所有请求的权限是否都被授予\\n      return permissions.every(permission =>\\n      abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED ===\\n      atManager.checkAccessTokenSync(tokenID, permission)\\n      );\\n    }\\n  }\\n\\n  // 异步静态方法用于请求用户授权指定的权限\\n  static async requestPermission(permissions: Permissions[]): Promise<boolean> {\\n    // 创建一个访问令牌管理器实例\\n    let atManager: abilityAccessCtrl.AtManager = abilityAccessCtrl.createAtManager();\\n\\n    // 获取上下文（这里假设getContext是一个可以获取到UI能力上下文的方法）\\n    let context: Context = getContext() as common.UIAbilityContext;\\n\\n    // 请求用户授权指定的权限\\n    const result = await atManager.requestPermissionsFromUser(context, permissions);\\n\\n    // 检查请求结果是否成功（authResults数组中每个元素都应该是0，表示成功）\\n    return !!result.authResults.length && result.authResults.every(authResults => authResults === 0);\\n  }\\n}\\n\\n```\\n\\n\\n\\n\\n\\n### 页面中使用权限代码\\n\\n`Index.ets`\\n\\n```typescript\\nimport { PermissionManager } from \'../utils/permissionMananger\'\\nimport { Permissions } from \'@kit.AbilityKit\'\\n\\n@Entry\\n@Component\\nstruct Index {\\n  // 1 申请权限\\n  fn1 = async () => {\\n    // 准备好需要申请的权限 麦克风权限\\n    const permissions: Permissions[] = [\\"ohos.permission.MICROPHONE\\"]\\n    // 检查是否拥有权限\\n    const isPermission = await PermissionManager.checkPermission(permissions)\\n    if (!isPermission) {\\n      //   如果没权限，就主动申请\\n      PermissionManager.requestPermission(permissions)\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\\"申请权限\\")\\n        .onClick(this.fn1)\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n![image-20240828224918956](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828224918956.png)\\n\\n## 实时语音识别相关步骤\\n\\n> 以下主要实现实时语音识别\\n\\n### 创建AI语音引擎\\n\\n创建AI语音引擎主要有以下几个步骤\\n\\n1. 声明AI语音引擎配置参数，主要有语种、区域信息等\\n\\n   ![image-20240828225611828](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828225611828.png)\\n\\n2. 调用开始创建 `createEngine` 方法开始创建，并且返回 AI语音实例引擎\\n\\n\\n\\n\\n\\n### 设置AI语音监听回调\\n\\n在开始语音识别之前，需要先设置语音识别回调 `setListener` 。它主要有以下几个分类\\n\\n1. 开始识别回调\\n2. 事件回调\\n3. 识别结果回调\\n4. 识别完成回调\\n5. 识别错误回调\\n\\n![image-20240828225832286](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828225832286.png)\\n\\n### 开始监听实时语音\\n\\n需要先配置监听的参数，便可以调用`startListening`实现语音识别了\\n\\n参数配置  其中，实时语音识别和语音文件识别的主要配置在 `recognitionMode` 字段， **0 表示实时语音识别** \\n\\n![image-20240828230419298](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828230419298.png)\\n\\n\\n\\n### 封装好的语音识别代码\\n\\n`\\\\entry\\\\src\\\\main\\\\ets\\\\utils\\\\SpeechRecognizerManager.ets`\\n\\n```typescript\\nimport { speechRecognizer } from \'@kit.CoreSpeechKit\';\\n\\n\\nclass SpeechRecognizerManager {\\n  /**\\n   * 语种信息\\n   * 语音模式：长\\n   */\\n  private static extraParam: Record<string, Object> = { \\"locate\\": \\"CN\\", \\"recognizerMode\\": \\"long\\" };\\n  private static initParamsInfo: speechRecognizer.CreateEngineParams = {\\n    /**\\n     * 地区信息\\n     * */\\n    language: \'zh-CN\',\\n    /**\\n     * 离线模式：1\\n     */\\n    online: 1,\\n    extraParams: this.extraParam\\n  };\\n  /**\\n   * 引擎\\n   */\\n  private static asrEngine: speechRecognizer.SpeechRecognitionEngine | null = null\\n  /**\\n   * 录音结果\\n   */\\n  static speechResult: speechRecognizer.SpeechRecognitionResult | null = null\\n  /**\\n   * 会话ID\\n   */\\n  private static sessionId: string = \\"asr\\" + Date.now()\\n\\n  /**\\n   * 创建引擎\\n   */\\n  private static async createEngine() {\\n    // 设置创建引擎参数\\n    SpeechRecognizerManager.asrEngine = await speechRecognizer.createEngine(SpeechRecognizerManager.initParamsInfo)\\n  }\\n\\n  /**\\n   * 设置回调\\n   */\\n  private static setListener(callback: (srr: speechRecognizer.SpeechRecognitionResult) => void = () => {\\n  }) {\\n    // 创建回调对象\\n    let setListener: speechRecognizer.RecognitionListener = {\\n      // 开始识别成功回调\\n      onStart(sessionId: string, eventMessage: string) {\\n      },\\n      // 事件回调\\n      onEvent(sessionId: string, eventCode: number, eventMessage: string) {\\n      },\\n      // 识别结果回调，包括中间结果和最终结果\\n      onResult(sessionId: string, result: speechRecognizer.SpeechRecognitionResult) {\\n        SpeechRecognizerManager.speechResult = result\\n        callback && callback(result)\\n      },\\n      // 识别完成回调\\n      onComplete(sessionId: string, eventMessage: string) {\\n      },\\n      // 错误回调，错误码通过本方法返回\\n      // 如：返回错误码1002200006，识别引擎正忙，引擎正在识别中\\n      // 更多错误码请参考错误码参考\\n      onError(sessionId: string, errorCode: number, errorMessage: string) {\\n      },\\n    }\\n    // 设置回调\\n    SpeechRecognizerManager.asrEngine?.setListener(setListener);\\n  }\\n\\n  /**\\n   * 开始监听\\n   * */\\n  static startListening() {\\n    // 设置开始识别的相关参数\\n    let recognizerParams: speechRecognizer.StartParams = {\\n      // 会话id\\n      sessionId: SpeechRecognizerManager.sessionId,\\n      // 音频配置信息。\\n      audioInfo: {\\n        // 音频类型。 当前仅支持“pcm”\\n        audioType: \'pcm\',\\n        // 音频的采样率。 当前仅支持16000采样率\\n        sampleRate: 16000,\\n        // 音频返回的通道数信息。 当前仅支持通道1。\\n        soundChannel: 1,\\n        // 音频返回的采样位数。 当前仅支持16位\\n        sampleBit: 16\\n      },\\n      //   录音识别\\n      extraParams: {\\n        // 0:实时录音识别  会自动打开麦克风 录制实时语音\\n        \\"recognitionMode\\": 0,\\n        //   最大支持音频时长\\n        maxAudioDuration: 60000\\n      }\\n    }\\n    // 调用开始识别方法\\n    SpeechRecognizerManager.asrEngine?.startListening(recognizerParams);\\n  };\\n\\n  /**\\n   * 取消识别\\n   */\\n  static cancel() {\\n    SpeechRecognizerManager.asrEngine?.cancel(SpeechRecognizerManager.sessionId)\\n  }\\n\\n  /**\\n   * 释放ai语音转文字引擎\\n   */\\n  static shutDown() {\\n    SpeechRecognizerManager.asrEngine?.shutdown()\\n  }\\n\\n  /**\\n   * 停止并且释放资源\\n   */\\n  static async release() {\\n    SpeechRecognizerManager.cancel()\\n    SpeechRecognizerManager.shutDown()\\n\\n  }\\n\\n  /**\\n   * 初始化ai语音转文字引擎\\n   */\\n  static async init(callback: (srr: speechRecognizer.SpeechRecognitionResult) => void = () => {\\n  }) {\\n    await SpeechRecognizerManager.createEngine()\\n    SpeechRecognizerManager.setListener(callback)\\n    SpeechRecognizerManager.startListening()\\n  }\\n}\\n\\nexport default SpeechRecognizerManager\\n```\\n\\n### 页面中调用语音识别代码\\n\\n```typescript\\nimport { PermissionManager } from \'../utils/permissionMananger\'\\nimport { Permissions } from \'@kit.AbilityKit\'\\nimport SpeechRecognizerManager from \'../utils/SpeechRecognizerManager\'\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  text: string = \\"\\"\\n  // 1 申请权限\\n  fn1 = async () => {\\n    // 准备好需要申请的权限 麦克风权限\\n    const permissions: Permissions[] = [\\"ohos.permission.MICROPHONE\\"]\\n    // 检查是否拥有权限\\n    const isPermission = await PermissionManager.checkPermission(permissions)\\n    if (!isPermission) {\\n      //   如果没权限，就主动申请\\n      PermissionManager.requestPermission(permissions)\\n    }\\n  }\\n  // 2 实时语音识别\\n  fn2 = () => {\\n    SpeechRecognizerManager.init(res => {\\n      console.log(\\"实时语音识别\\", JSON.stringify(res))\\n      this.text = res.result\\n    })\\n  }\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Text(this.text)\\n\\n      Button(\\"申请权限\\")\\n        .onClick(this.fn1)\\n      Button(\\"实时语音识别\\")\\n        .onClick(this.fn2)\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n---\\n\\n![PixPin_2024-08-28_23-19-49](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/PixPin_2024-08-28_23-19-49.gif)\\n\\n---\\n\\n### 语音识别结果分析\\n\\n**语音识别成功后的数据格式如下**\\n\\n```\\n实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多\\"}\\nI     实时语音识别 {\\"isFinal\\":true,\\"isLast\\":false,\\"result\\":\\"是否给你承诺的太多？\\"}\\nI     实时语音识别 {\\"isFinal\\":false,\\"isLast\\":false,\\"result\\":\\"\\"}\\n```\\n\\n其中需要关注的是：\\n\\n1. 识别功能是持续触发的，当收集到声音时持续触发\\n\\n2. isFinal 表示一个句子是否结束\\n\\n   ![image-20240828232352345](HarmonyNext%E4%B8%AD%E7%9A%84AI%E8%AF%AD%E9%9F%B3%E5%8A%9F%E8%83%BD%E4%BD%93%E9%AA%8C.assets/image-20240828232352345.png)\\n\\n3. isLast 表示这一次语音识别是否结束\\n\\n\\n\\n\\n\\n\\n\\n## 总结\\n\\n**HarmonyOSNext**中集成了强大的AI功能。Core Speech Kit（基础语音服务）是它提供的众多AI功能中的一种。\\n\\nCore Speech Kit（基础语音服务）集成了语音类基础AI能力，包括文本转语音（TextToSpeech）及语音识别（SpeechRecognizer）能\\n\\n力，便于用户与设备进行互动，实现将实时输入的语音与文本之间相互转换。\\n\\n简单来讲Core Speech Kit主要提供了两大语音AI功能：\\n\\n1. **语音识别**\\n2. **文本转语音**\\n\\n其中语音识别又可以实现：\\n\\n1. **实时语音转文本** \\n2. **声音文件转文本**\\n\\n\\n\\n本文主要实现了  **实时语音转文本** ， **声音文件转文本** 将会在下文讲解。"}'),u={name:"鸿蒙开发技巧/三文带你轻松上手鸿蒙的AI语音/三文带你轻松上手鸿蒙的AI语音01-实时语音识别/01-实时语音识别.md"};function g(d,s,b,y,m,F){return a(),i("div",null,[...s[0]||(s[0]=[l("",75)])])}const C=n(u,[["render",g]]);export{A as __pageData,C as default};
